mapper.select:
        SELECT entrance_id type,sum(sum) count
        FROM ntc_entrance_report a
        WHERE service = 18
		  AND report_time between #{start} and #{end}
        group by entrance_id;

SELECT  #{end} time ,service type,SUM(sum)  count
FROM ntc_service_report
WHERE report_time between #{start} AND #{end}
GROUP BY service;
